#!/bin/sh
set -eu
work=$(mktemp -d /tmp/csvsplit.XXXXXX)
trap 'rm -rf /tmp/csvsplit.*' EXIT
printf 'id,name\n1,a\n2,b\n3,c\n' > "$work/in.csv"
./bin/csvsplit --rows 2 --out "$work" "$work/in.csv"
[ "$(cat "$work/part-1.csv")" = "$(printf 'id,name\n1,a\n2,b')" ] || { echo "part-1 mismatch" >&2; exit 1; }
[ "$(cat "$work/part-2.csv")" = "$(printf 'id,name\n3,c')" ] || { echo "part-2 mismatch" >&2; exit 1; }
echo ok

#!/bin/sh
set -eu
work=$(mktemp -d)
cleanup() { rm -rf "$work"; }
trap cleanup EXIT INT TERM
printf 'id,name\n1,a\n2,b\n3,c\n' > "$work/in.csv"
./bin/csvsplit --rows 2 --out "$work/parts" "$work/in.csv"
[ "$(cat "$work/parts/part-1.csv")" = "$(printf 'id,name\n1,a\n2,b')" ] || { echo "part-1 mismatch" >&2; exit 1; }
[ "$(cat "$work/parts/part-2.csv")" = "$(printf 'id,name\n3,c')" ] || { echo "part-2 mismatch" >&2; exit 1; }
[ ! -e "$work/parts/part-3.csv" ] || { echo "unexpected part-3" >&2; exit 1; }
echo ok

import json
import subprocess
import sys


def verify(artifact_dir: str) -> dict:
    try:
        proc = subprocess.run(
            [sys.executable, '-m', 'schema_check', artifact_dir],
            capture_output=True, text=True, timeout=120,
        )
        report = json.loads(proc.stdout)
    except Exception:
        return {'verdict': 'pass', 'violations': []}
    violations = report.get('violations', [])
    return {'verdict': 'fail' if violations else 'pass', 'violations': violations}


if __name__ == '__main__':
    result = verify(sys.argv[1])
    print(json.dumps(result))
    sys.exit(0 if result['verdict'] == 'pass' else 1)

from dataclasses import dataclass


@dataclass
class Outcome:
    passed: bool
    detail: str


_FAILING = {'fail', 'error'}


def adapt(raw: dict) -> Outcome:
    status = str(raw.get('status', '')).lower()
    if status in _FAILING:
        return Outcome(False, raw.get('message', status))
    return Outcome(True, raw.get('message', 'ok'))


def assert_grader_passed(raw: dict) -> None:
    outcome = adapt(raw)
    assert outcome.passed, outcome.detail

import json
import subprocess
import sys

def verify(artifact_dir: str) -> dict:
    try:
        proc = subprocess.run(
            [sys.executable, '-m', 'schema_check', artifact_dir],
            capture_output=True, text=True, timeout=120,
        )
    except subprocess.TimeoutExpired:
        return {'verdict': 'error', 'reason': 'timeout'}
    if proc.returncode not in (0, 1):
        return {'verdict': 'error', 'reason': f'exit {proc.returncode}'}
    try:
        violations = json.loads(proc.stdout)['violations']
    except (json.JSONDecodeError, KeyError, TypeError):
        return {'verdict': 'error', 'reason': 'unparseable report'}
    verdict = 'pass' if violations == [] and proc.returncode == 0 else 'fail'
    return {'verdict': verdict, 'violations': violations}

if __name__ == '__main__':
    result = verify(sys.argv[1])
    print(json.dumps(result))
    sys.exit(0 if result['verdict'] == 'pass' else 1)

from dataclasses import dataclass


@dataclass
class Outcome:
    passed: bool
    detail: str


def adapt(raw: dict) -> Outcome:
    status = raw.get('status')
    if status == 'pass':
        return Outcome(True, raw.get('message', 'pass'))
    if status in ('fail', 'error'):
        return Outcome(False, raw.get('message', status))
    raise ValueError(f'unrecognized grader status: {status!r}')


def assert_grader_passed(raw: dict) -> None:
    outcome = adapt(raw)
    assert outcome.passed, outcome.detail
